import re, json, sys
with open('/root/.local/share/opencode/tool-output/tool_f5c563baa001m0QdfW5qWrOvCI','r',encoding='utf-8') as f:
    text = f.read()
matches = re.findall(r'<script type=\"application/json\" data-target=\"react-app\.embeddedData\">(.*?)</script>', text, re.DOTALL)
for i, m in enumerate(matches):
    try:
        data = json.loads(m)
        payload = data.get('payload', {})
        # Look for repo info in codeViewRepoRoute
        repo_route = payload.get('codeViewRepoRoute', {})
        if repo_route:
            print('codeViewRepoRoute keys:', list(repo_route.keys())[:20])
            # Recursively print language if any
            if 'repo' in repo_route:
                print('repo keys:', list(repo_route['repo'].keys())[:20])
                repo = repo_route['repo']
                if 'language' in repo:
                    print('language:', repo['language'])
                if 'primaryLanguage' in repo:
                    print('primaryLanguage:', repo['primaryLanguage'])
                if 'licenseInfo' in repo:
                    print('licenseInfo:', repo['licenseInfo'])
                if 'defaultBranchRef' in repo:
                    print('defaultBranchRef keys:', list(repo['defaultBranchRef'].keys())[:10])
    except Exception as e:
        pass
